def max_path_sum(root):
    def arm(node):
        if node is None:
            return 0
        return node.val + max(0, arm(node.left), arm(node.right))

    best = float("-inf")
    stack = [root]
    while stack:
        node = stack.pop()
        bend = node.val + max(0, arm(node.left)) + max(0, arm(node.right))
        best = max(best, bend)
        stack += [c for c in (node.left, node.right) if c is not None]
    return best
